        const { useState, useEffect, useRef, useCallback } = React;

        // Layers that are always visible (no toggle)
        const ALWAYS_ON_LAYERS = ['district_oranim'];

        // GeoJSON data files
        // Find the best label point inside a polygon (visual center)
        function pointInPolygon(pt, ring) {
            let inside = false;
            for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
                const xi = ring[i][0], yi = ring[i][1];
                const xj = ring[j][0], yj = ring[j][1];
                if ((yi > pt[1]) !== (yj > pt[1]) && pt[0] < (xj - xi) * (pt[1] - yi) / (yj - yi) + xi)
                    inside = !inside;
            }
            return inside;
        }

        function segmentsIntersect(a1, a2, b1, b2) {
            const d1x = a2[0]-a1[0], d1y = a2[1]-a1[1];
            const d2x = b2[0]-b1[0], d2y = b2[1]-b1[1];
            const cross = d1x*d2y - d1y*d2x;
            if (Math.abs(cross) < 1e-12) return false;
            const t = ((b1[0]-a1[0])*d2y - (b1[1]-a1[1])*d2x) / cross;
            const u = ((b1[0]-a1[0])*d1y - (b1[1]-a1[1])*d1x) / cross;
            return t > 0 && t < 1 && u > 0 && u < 1;
        }

        function polygonsOverlap(ringA, ringB) {
            for (const pt of ringA) { if (pointInPolygon(pt, ringB)) return true; }
            for (const pt of ringB) { if (pointInPolygon(pt, ringA)) return true; }
            for (let i = 0; i < ringA.length - 1; i++) {
                for (let j = 0; j < ringB.length - 1; j++) {
                    if (segmentsIntersect(ringA[i], ringA[i+1], ringB[j], ringB[j+1])) return true;
                }
            }
            return false;
        }

        function getAllRings(geom) {
            if (!geom) return [];
            if (geom.type === 'Polygon') return geom.coordinates[0] ? [geom.coordinates[0]] : [];
            if (geom.type === 'MultiPolygon') {
                const rings = [];
                for (const poly of geom.coordinates) { if (poly[0]) rings.push(poly[0]); }
                return rings;
            }
            return [];
        }

        function ringBBox(ring) {
            let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
            for (const p of ring) {
                if (p[0] < minX) minX = p[0];
                if (p[0] > maxX) maxX = p[0];
                if (p[1] < minY) minY = p[1];
                if (p[1] > maxY) maxY = p[1];
            }
            return [minX, minY, maxX, maxY];
        }

        function bboxesOverlap(a, b) {
            return !(a[2] < b[0] || b[2] < a[0] || a[3] < b[1] || b[3] < a[1]);
        }

        // Sample grid inside ringA's bbox, count samples in A and in (A ∩ B).
        // Returns (samples in A ∩ B) / (samples in A). 0 if A area is ~0.
        function sampleOverlapFraction(ringA, ringB, n) {
            const [minX, minY, maxX, maxY] = ringBBox(ringA);
            const stepX = (maxX - minX) / n, stepY = (maxY - minY) / n;
            let inA = 0, inBoth = 0;
            for (let i = 0; i < n; i++) {
                const x = minX + (i + 0.5) * stepX;
                for (let j = 0; j < n; j++) {
                    const y = minY + (j + 0.5) * stepY;
                    if (pointInPolygon([x, y], ringA)) {
                        inA++;
                        if (pointInPolygon([x, y], ringB)) inBoth++;
                    }
                }
            }
            return inA === 0 ? 0 : inBoth / inA;
        }

        // "Significant" overlap — majority of one polygon's area is inside the other.
        // Grid-sampled area ratio in both directions; if either >= threshold, count as overlap.
        function significantOverlap(ringA, ringB, threshold = 0.5, samples = 14) {
            if (!bboxesOverlap(ringBBox(ringA), ringBBox(ringB))) return false;
            if (sampleOverlapFraction(ringA, ringB, samples) >= threshold) return true;
            if (sampleOverlapFraction(ringB, ringA, samples) >= threshold) return true;
            return false;
        }

        // Compute pairs of plans whose geometries overlap.
        // Returns a Map: taba -> Set of overlapping tabas.
        function computeOverlapMap(features) {
            // Build ring/bbox per feature (skip plans without taba or geometry)
            const items = [];
            for (const f of features) {
                const taba = String(f.properties.taba || '').trim();
                if (!taba) continue;
                const rings = getAllRings(f.geometry);
                if (!rings.length) continue;
                items.push({ taba, rings, bboxes: rings.map(ringBBox) });
            }
            const map = new Map();
            for (let i = 0; i < items.length; i++) {
                for (let j = i + 1; j < items.length; j++) {
                    const A = items[i], B = items[j];
                    if (A.taba === B.taba) continue;
                    // bbox pre-filter across any ring pair
                    let bboxHit = false;
                    for (const ba of A.bboxes) {
                        for (const bb of B.bboxes) {
                            if (bboxesOverlap(ba, bb)) { bboxHit = true; break; }
                        }
                        if (bboxHit) break;
                    }
                    if (!bboxHit) continue;
                    // Deeper check: "significant" area overlap (>= 50% of either polygon),
                    // not just any touching. Any ring-pair above threshold qualifies.
                    let overlap = false;
                    for (const ra of A.rings) {
                        for (const rb of B.rings) {
                            if (significantOverlap(ra, rb)) { overlap = true; break; }
                        }
                        if (overlap) break;
                    }
                    if (overlap) {
                        if (!map.has(A.taba)) map.set(A.taba, new Set());
                        if (!map.has(B.taba)) map.set(B.taba, new Set());
                        map.get(A.taba).add(B.taba);
                        map.get(B.taba).add(A.taba);
                    }
                }
            }
            return map;
        }

        // Area-weighted centroid of a Polygon/MultiPolygon. Returns [lng, lat] or null.
        function geomCentroid(geometry) {
            if (!geometry) return null;
            let ring;
            if (geometry.type === 'MultiPolygon') {
                let maxArea = 0;
                for (const poly of geometry.coordinates) {
                    const r = poly[0]; if (!r) continue;
                    let a = 0;
                    for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
                        a += r[j][0] * r[i][1] - r[i][0] * r[j][1];
                    }
                    a = Math.abs(a);
                    if (a > maxArea) { maxArea = a; ring = r; }
                }
            } else if (geometry.type === 'Polygon') {
                ring = geometry.coordinates[0];
            } else if (geometry.type === 'Point') {
                return geometry.coordinates.slice(0, 2);
            }
            if (!ring || ring.length === 0) return null;
            let area = 0, cx = 0, cy = 0;
            for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
                const a = ring[j][0] * ring[i][1] - ring[i][0] * ring[j][1];
                area += a;
                cx += (ring[j][0] + ring[i][0]) * a;
                cy += (ring[j][1] + ring[i][1]) * a;
            }
            area *= 0.5;
            if (Math.abs(area) > 1e-12) return [cx / (6 * area), cy / (6 * area)];
            return [ring[0][0], ring[0][1]];
        }

        // True if [lng,lat] point is inside any ring of a Polygon/MultiPolygon geometry.
        function pointInGeometry(pt, geometry) {
            if (!pt || !geometry) return false;
            const polys = geometry.type === 'MultiPolygon' ? geometry.coordinates
                       : geometry.type === 'Polygon' ? [geometry.coordinates] : [];
            for (const poly of polys) {
                if (!poly[0]) continue;
                if (pointInPolygon(pt, poly[0])) return true;
            }
            return false;
        }

        // True if plan passes the active report scope (projector boundary).
        // No active scope => always true. Empty plan_name => false (can't classify).
        function planPassesReportScope(planName) {
            const scope = window.__reportScope;
            if (!scope) return true;
            if (!planName) return false;
            if (scope === 'projector_talpiot') {
                const set = window.__inProjectorTalpiotPlans;
                return set ? set.has(planName) : false;
            }
            return true;
        }

        // Pre-compute: set of plan_names inside the projector boundary, plus a
        // Map<plan_name, sub_name> classifying each plan into one of the 5 internal sub-polygons.
        const PROJECTOR_TALPIOT_MINAHAK = 'פרוייקטור תלפיות';
        function buildProjectorTalpiotPlanSet(gd) {
            const out = new Set();
            const subByPlan = new Map();
            const projGeom = gd && gd.projector_talpiot && gd.projector_talpiot.features
                && gd.projector_talpiot.features[0] && gd.projector_talpiot.features[0].geometry;
            if (!projGeom || !gd.plans) {
                window.__inProjectorTalpiotPlans = out;
                window.__projectorTalpiotSubByPlan = subByPlan;
                return out;
            }
            const subFeats = (gd.projector_talpiot_subs && gd.projector_talpiot_subs.features) || [];
            for (const f of gd.plans.features) {
                const c = geomCentroid(f.geometry);
                if (!c) continue;
                if (!pointInGeometry(c, projGeom)) continue;
                const pn = (f.properties && f.properties.plan_name) || '';
                if (!pn) continue;
                out.add(pn);
                for (const sf of subFeats) {
                    if (pointInGeometry(c, sf.geometry)) {
                        subByPlan.set(pn, (sf.properties && sf.properties.name) || 'אחר');
                        break;
                    }
                }
            }
            window.__inProjectorTalpiotPlans = out;
            window.__projectorTalpiotSubByPlan = subByPlan;
            return out;
        }

        // Effective minahak / sub when a report scope is active.
        // In projector scope: all plans roll up under a single virtual minahak, and the
        // sub-neighborhood comes from the 5 internal polygons (not the plan's own field).
        function effectiveMinahakInScope(realMinahak) {
            return window.__reportScope === 'projector_talpiot' ? PROJECTOR_TALPIOT_MINAHAK : realMinahak;
        }
        function effectiveSubInScope(planName, fallbackSub) {
            if (window.__reportScope === 'projector_talpiot') {
                const m = window.__projectorTalpiotSubByPlan;
                return (m && m.get(planName)) || fallbackSub || 'אחר';
            }
            return fallbackSub;
        }
        function effectiveMinahakOrderInScope(realOrder) {
            return window.__reportScope === 'projector_talpiot' ? [PROJECTOR_TALPIOT_MINAHAK] : realOrder;
        }

        function visualCenter(geometry, excludeRings) {
            // For MultiPolygon, find the largest part by area
            let ring;
            if (geometry.type === 'MultiPolygon') {
                let maxArea = 0;
                try { ring = geometry.coordinates[0][0]; } catch(e) { return null; }
                if (!ring) return null;
                for (const poly of geometry.coordinates) {
                    const r = poly[0];
                    let a = 0;
                    for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
                        a += r[j][0] * r[i][1] - r[i][0] * r[j][1];
                    }
                    a = Math.abs(a);
                    if (a > maxArea) { maxArea = a; ring = r; }
                }
            } else {
                ring = geometry.coordinates[0];
            }
            // Proper polygon centroid using signed area formula
            let area = 0, cx = 0, cy = 0;
            for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
                const a = ring[j][0] * ring[i][1] - ring[i][0] * ring[j][1];
                area += a;
                cx += (ring[j][0] + ring[i][0]) * a;
                cy += (ring[j][1] + ring[i][1]) * a;
            }
            area *= 0.5;
            if (Math.abs(area) > 1e-12) { cx /= (6 * area); cy /= (6 * area); }
            else { cx = ring[0][0]; cy = ring[0][1]; }
            if (pointInPolygon([cx, cy], ring)) {
                const inExclude = excludeRings && excludeRings.some(er => pointInPolygon([cx, cy], er));
                if (!inExclude) return [cy, cx];
            }
            // Bbox
            let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
            for (const c of ring) {
                if (c[0] < minX) minX = c[0]; if (c[1] < minY) minY = c[1];
                if (c[0] > maxX) maxX = c[0]; if (c[1] > maxY) maxY = c[1];
            }
            // Iterative grid search (polylabel-like): 4 rounds, each 12x12
            let bestPt = [cy, cx], bestDist = -1;
            let sMinX = minX, sMinY = minY, sMaxX = maxX, sMaxY = maxY;
            for (let round = 0; round < 4; round++) {
                const N = 12;
                const stepX = (sMaxX - sMinX) / N, stepY = (sMaxY - sMinY) / N;
                for (let xi = 0; xi < N; xi++) {
                    const gx = sMinX + (xi + 0.5) * stepX;
                    for (let yi = 0; yi < N; yi++) {
                        const gy = sMinY + (yi + 0.5) * stepY;
                        if (!pointInPolygon([gx, gy], ring)) continue;
                        if (excludeRings && excludeRings.some(er => pointInPolygon([gx, gy], er))) continue;
                        let minEdgeDist = Infinity;
                        const allRings = excludeRings ? [ring, ...excludeRings] : [ring];
                        for (const edgeRing of allRings) {
                            for (let i = 0, j = edgeRing.length - 1; i < edgeRing.length; j = i++) {
                                const ax = edgeRing[j][0], ay = edgeRing[j][1];
                                const bx = edgeRing[i][0], by = edgeRing[i][1];
                                const abx = bx-ax, aby = by-ay;
                                const ab2 = abx*abx + aby*aby;
                                const t = ab2 > 0 ? Math.max(0, Math.min(1, ((gx-ax)*abx+(gy-ay)*aby)/ab2)) : 0;
                                const d = (gx-ax-t*abx)*(gx-ax-t*abx)+(gy-ay-t*aby)*(gy-ay-t*aby);
                                if (d < minEdgeDist) minEdgeDist = d;
                            }
                        }
                        if (minEdgeDist > bestDist) { bestDist = minEdgeDist; bestPt = [gy, gx]; }
                    }
                }
                // Zoom into area around best point for next round
                const r = Math.max(stepX, stepY);
                sMinX = bestPt[1] - r; sMaxX = bestPt[1] + r;
                sMinY = bestPt[0] - r; sMaxY = bestPt[0] + r;
            }
            return bestPt; // [lat, lng]
        }

