        // Sum of existing housing units (NUM_APTS_C from municipal buildings layer)
        // for buildings whose centroid falls inside a closed polygon (lng,lat ring).
        function sumExistingUnitsInPolygon(polygonLngLat, buildings) {
            if (!buildings || !buildings.features || !polygonLngLat || polygonLngLat.length < 3) return 0;
            function pip(pt, ring) {
                const x = pt[0], y = pt[1];
                let inside = false;
                for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
                    const xi = ring[i][0], yi = ring[i][1];
                    const xj = ring[j][0], yj = ring[j][1];
                    if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi))
                        inside = !inside;
                }
                return inside;
            }
            let sum = 0;
            const feats = buildings.features;
            for (let i = 0; i < feats.length; i++) {
                const c = feats[i].geometry && feats[i].geometry.coordinates;
                if (!c) continue;
                if (pip(c, polygonLngLat)) sum += (feats[i].properties && feats[i].properties.units) || 0;
            }
            return sum;
        }

        // Aggregate education_shanaton institutions matching a filter — returns same
        // shape as computeExistingEduPerSub's per-sub block (ganim_count, yesodi_classes, etc.).
        function aggregateEduFeatures(matchedFeatures) {
            const out = { ganim_count: 0, gan_special_count: 0, yesodi_count: 0, yesodi_classes: 0, alyesodi_count: 0, alyesodi_classes: 0, special_classes: 0, maon_count: 0, maon_classes: 0, total_classes: 0, students: 0, byKey: { gan: [], yesodi: [], al_yesodi: [], maon: [] } };
            matchedFeatures.forEach(f => {
                (f.properties.institutions || []).forEach(inst => {
                    const t = inst.type;
                    const studs = inst.students || 0;
                    out.students += studs;
                    const baseInfo = { name: inst.name, type: t, students: studs, address: f.properties.address, semel: inst.semel_chinuch, pikuach: inst.pikuach };
                    if (t === 'מעון') {
                        const c2 = inst.classes || 1;
                        out.maon_count++; out.maon_classes += c2; out.total_classes += c2;
                        out.byKey.maon.push({ ...baseInfo, classes: c2, avg: 0 });
                    } else if (t === 'גן') {
                        out.ganim_count++; out.total_classes++;
                        out.byKey.gan.push({ ...baseInfo, classes: 1, avg: studs });
                    } else if (t === 'גן חינוך מיוחד') {
                        out.gan_special_count++; out.total_classes++; out.special_classes++;
                        out.byKey.gan.push({ ...baseInfo, classes: 1, avg: studs, special: true });
                    } else if (t === 'יסודי' || t === 'יסודי/תיכון') {
                        out.yesodi_count++;
                        const k = (inst.kitot_regilot || 0) + (inst.kitot_mekadmot || 0);
                        const c2 = k > 0 ? k : Math.max(1, Math.round(studs / 27));
                        out.yesodi_classes += c2;
                        out.special_classes += (inst.kitot_mekadmot || 0);
                        out.total_classes += c2;
                        out.byKey.yesodi.push({ ...baseInfo, classes: c2, avg: c2 ? Math.round(studs / c2) : 0, classes_estimated: !(k > 0), special_classes: inst.kitot_mekadmot || 0 });
                    } else if (t === 'תיכון' || t === 'חטיבה' || t === 'אולפנה' || t === 'מדרשייה' || t === 'ישיבה') {
                        out.alyesodi_count++;
                        const k = (inst.kitot_regilot || 0) + (inst.kitot_mekadmot || 0);
                        const c2 = k > 0 ? k : Math.max(1, Math.round(studs / 28));
                        out.alyesodi_classes += c2;
                        out.special_classes += (inst.kitot_mekadmot || 0);
                        out.total_classes += c2;
                        out.byKey.al_yesodi.push({ ...baseInfo, classes: c2, avg: c2 ? Math.round(studs / c2) : 0, classes_estimated: !(k > 0), special_classes: inst.kitot_mekadmot || 0 });
                    }
                });
            });
            return out;
        }

