        //   • Single-item without numbers → counts as 1
        //   • Generic "מבנים ומוסדות ציבור (5000)" → adds 5000 to uncategorizedSqm
        function parseFacilitiesFromText(text) {
            const counts = {}; PARSER_KEYS.forEach(k => counts[k] = 0);
            let uncategorizedSqm = 0;
            if (!text || !text.trim()) return { counts, uncategorizedSqm };
            const items = text.split(/[;,]/);
            for (const raw of items) {
                const t = (raw || '').trim();
                if (!t) continue;
                // sqm in parentheses (possibly followed by 'מ"ר') — used for generic items
                const sqmMatch = t.match(/\(\s*([\d,]+(?:\.\d+)?)\s*(?:מ"ר|מ״ר|מר)?\s*\)/);
                const sqm = sqmMatch ? parseFloat(sqmMatch[1].replace(/,/g, '')) : 0;
                // "N כיתות" — explicit class count (highest priority)
                const classesMatch = t.match(/(\d+)\s*כיתות?/);
                const explicitClasses = classesMatch ? parseInt(classesMatch[1]) : 0;
                // Leading "N " — number of facilities (e.g., "2 בתי כנסת")
                const leadMatch = t.match(/^(\d+)\s/);
                const leadCount = leadMatch ? parseInt(leadMatch[1]) : 0;
                const count = explicitClasses || leadCount || 1;
                let matched = false;
                // Education — al_yesodi (longer/more-specific phrases first)
                if (/(תיכון|חטיבה|אולפנה|מדרשייה|מדרשיה|ישיבה גבוהה|ישיבה תיכונית|על[\- ]יסודי|בתי ספר על|בית ספר על|ספר על יסודי)/.test(t)) { counts.al_yesodi += count; matched = true; }
                else if (/(מעון|מעונות יום|פעוטון)/.test(t)) { counts.maon += count; matched = true; }
                else if (/(גן ילדים|גני ילדים|גנון|גן חינוך)/.test(t) || /(?:^|[^א-ת])(?:כיתות?\s+)?גן(?:[^א-ת]|$)/.test(t)) { counts.gan += count; matched = true; }
                else if (/(יסודי|בית ספר|בי"ס|בי״ס|ביה"ס|ביה״ס|בית-ספר)/.test(t)) { counts.yesodi += count; matched = true; }
                // Religious
                else if (/(בית כנסת|ביכ"נ|ביכ״נ|בית-כנסת|בתי כנסת|בית כנסת)/.test(t)) { counts.synagogue += count; matched = true; }
                else if (/(מקווה|מקוואות)/.test(t)) { counts.mikve += count; matched = true; }
                // Community / culture
                else if (/(מתנ"ס|מתנ״ס|מרכז קהילתי|שלוחת מתנס|מועדון קהילתי)/.test(t)) { counts.matnas += count; matched = true; }
                else if (/(ספרייה|ספריה)/.test(t)) { counts.library += count; matched = true; }
                // Sports
                else if (/(אולם ספורט|מגרש ספורט|בריכת שחייה|בריכה ציבורית|מרכז ספורט|מתקני ספורט|מבנים ומתקנים לפעילויות ספורט|פעילויות ספורט|פנאי וספורט|אולם)/.test(t)) { counts.sport_hall += count; matched = true; }
                // Health
                else if (/(טיפת חלב|תחנת בריאות)/.test(t)) { counts.tipat_chalav += count; matched = true; }
                else if (/(מרפאה|קופת חולים)/.test(t)) { counts.clinic += count; matched = true; }
                // Welfare
                else if (/(לשכת רווחה|מחלקה לשירותים חברתיים)/.test(t)) { counts.welfare_dept += count; matched = true; }
                else if (/(מועדון נוער|מועדונית|מרכז נוער)/.test(t)) { counts.noar_club += count; matched = true; }
                else if (/(מועדון קשיש|מועדון לקשיש|מועדון לאזרחים ותיקים|אזרחים ותיקים)/.test(t)) { counts.elderly_club += count; matched = true; }
                else if (/(מרכז יום לקשיש|מרכז יום|תשושים|תשושי גוף)/.test(t)) { counts.elderly_day += count; matched = true; }
                // Uncategorized generic public buildings — accumulate sqm
                if (!matched && /(מבנים ומוסדות|מבני ציבור|מוסדות ציבור|מוסדות כלל ציבור|שב"צ|שבצ|שצ"פ|שצ״פ|שטחי ציבור)/.test(t)) {
                    uncategorizedSqm += sqm;
                }
            }
            return { counts, uncategorizedSqm };
        }

        // Returns true if [lng,lat] (or {lng,lat}) point is inside any feature polygon of layer (e.g. minahak_gonen)
        function pointInLayer(pt, layer) {
            if (!layer || !layer.features) return false;
            const lng = (pt && pt.lng != null) ? pt.lng : pt[0];
            const lat = (pt && pt.lat != null) ? pt.lat : pt[1];
            function ringHit(ring) {
                let inside = false;
                for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
                    const xi = ring[i][0], yi = ring[i][1];
                    const xj = ring[j][0], yj = ring[j][1];
                    if (((yi > lat) !== (yj > lat)) && (lng < (xj - xi) * (lat - yi) / (yj - yi + 1e-15) + xi))
                        inside = !inside;
                }
                return inside;
            }
            for (const f of layer.features) {
                const g = f.geometry; if (!g) continue;
                if (g.type === 'Polygon') { if (ringHit(g.coordinates[0])) return true; }
                else if (g.type === 'MultiPolygon') {
                    for (const poly of g.coordinates) { if (ringHit(poly[0])) return true; }
                }
            }
            return false;
        }

        // Filter education_shanaton features whose point lies inside the given plan geometry.
        function eduFeaturesInPlanGeometry(planGeom, eduFeats) {
            if (!planGeom || !planGeom.coordinates || !eduFeats) return [];
            function ringHit(lng, lat, ring) {
                let inside = false;
                for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
                    const xi = ring[i][0], yi = ring[i][1];
                    const xj = ring[j][0], yj = ring[j][1];
                    if (((yi > lat) !== (yj > lat)) && (lng < (xj - xi) * (lat - yi) / (yj - yi + 1e-15) + xi))
                        inside = !inside;
                }
                return inside;
            }
            function inGeom(lng, lat) {
                if (planGeom.type === 'Polygon') return ringHit(lng, lat, planGeom.coordinates[0]);
                if (planGeom.type === 'MultiPolygon') {
                    for (const poly of planGeom.coordinates) { if (ringHit(lng, lat, poly[0])) return true; }
                }
                return false;
            }
            return eduFeats.filter(f => {
                const c = f.geometry && f.geometry.coordinates;
                return c && inGeom(c[0], c[1]);
            });
        }

        function eduFeaturesInPolygon(polygonLngLat, gd) {
            if (!gd || !gd.education_shanaton || !polygonLngLat || polygonLngLat.length < 3) return [];
            const ring = polygonLngLat;
            function pip(pt) {
                const x = pt[0], y = pt[1];
                let inside = false;
                for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
                    const xi = ring[i][0], yi = ring[i][1];
                    const xj = ring[j][0], yj = ring[j][1];
                    if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi))
                        inside = !inside;
                }
                return inside;
            }
            return gd.education_shanaton.features.filter(f => {
                const c = f.geometry && f.geometry.coordinates;
                return c && pip(c);
            });
        }

        function eduFeaturesInRadius(centerLatLng, radiusMeters, gd) {
            if (!gd || !gd.education_shanaton || !centerLatLng) return [];
            return gd.education_shanaton.features.filter(f => {
                const c = f.geometry && f.geometry.coordinates;
                if (!c) return false;
                return centerLatLng.distanceTo(L.latLng(c[1], c[0])) <= radiusMeters;
            });
        }

        // Sum of existing housing units within a circle (center latlng + radius meters).
        function sumExistingUnitsInRadius(centerLatLng, radiusMeters, buildings) {
            if (!buildings || !buildings.features || !centerLatLng) return 0;
            let sum = 0;
            const feats = buildings.features;
            for (let i = 0; i < feats.length; i++) {
                const c = feats[i].geometry && feats[i].geometry.coordinates;
                if (!c) continue;
                if (centerLatLng.distanceTo(L.latLng(c[1], c[0])) <= radiusMeters) {
                    sum += (feats[i].properties && feats[i].properties.units) || 0;
                }
            }
            return sum;
        }

        // Map Hebrew property names to English aliases used by popup builders
        // Point-in-polygon: ray casting on a Leaflet polygon layer
        function leafletPip(layer, latlng) {
            const lng = latlng.lng, lat = latlng.lat;
            const geo = layer.feature.geometry;
            function pipRing(coords) {
                let inside = false;
                for (let i = 0, j = coords.length - 1; i < coords.length; j = i++) {
                    const xi = coords[i][0], yi = coords[i][1];
                    const xj = coords[j][0], yj = coords[j][1];
                    if ((yi > lat) !== (yj > lat) && lng < (xj - xi) * (lat - yi) / (yj - yi) + xi) {
                        inside = !inside;
                    }
                }
                return inside;
            }
            try {
                if (geo.type === 'MultiPolygon') {
                    for (const poly of geo.coordinates) {
                        if (pipRing(poly[0])) return true;
                    }
                    return false;
                } else if (geo.type === 'Polygon') {
                    return pipRing(geo.coordinates[0]);
                }
                return false;
            } catch(e) { return false; }
        }

