                const svgExisting = '<svg xmlns="http://www.w3.org/2000/svg" width="'+svgW+'" height="'+svgH+'" viewBox="0 0 '+svgW+' '+svgH+'">' + bgRect + kayamPaths + selSvg + '</svg>';
