                            const reason = reasonLocal || reasonFromGS;
                            rows.push({
                                taba: primary.taba,            // primary taba (for dedup/drilldown key)
                                tabas,                          // all tabas in cluster
                                plan_name: planNames.join(' + '),
                                plan_names: planNames,          // for drilldown detail
                                plan_summary: p.plan_summary || p.plan_name_he || '',
                                status_mavat: p.status_mavat || '',
                                minahak: p.minahak || '',
                                unitsAdd, unitsInPermits, gap, pctDone,
                                conditional: conditionalSum,
                                permitCount: mergedPermits.length,
                                countedPermits,
                                permits: mergedPermits,
                                inclusion,
                                scopeKey,
                                feature: primary.feature,
                                members,                        // full per-plan details for drilldown
                                isCluster: members.length > 1,
                                reason,
                                reasonFromGS,
                            });
