                        const minhakOptions = Array.from(new Set(rows.map(r => r.minahak).filter(Boolean))).sort();
                        const filteredRows = permitsGapMinhakFilter === 'all' ? rows : rows.filter(r => r.minahak === permitsGapMinhakFilter);

                        const sortCol = permitsGapSort.col;
