                                                    <span style={{fontSize:14,fontWeight:700,color:'#fff'}}>📝 סיבת חריגה</span>
                                                    {row.reasonFromGS && row.reasonFromGS !== reasonDraft && <span style={{fontSize:11,color:'#9ca3af'}}>(ב-GS: "{row.reasonFromGS}")</span>}
