                            printWin.document.write('<button onclick="window.print()" style="background:#4CAF50;color:#fff;border:none;border-radius:6px;padding:8px 16px;cursor:pointer;font-size:13px;font-weight:600">📄 שמור PDF (בחר יעד: שמור כ-PDF)</button>');
                            printWin.document.write('<button id="csvBtn" style="background:#2196F3;color:#fff;border:none;border-radius:6px;padding:8px 16px;cursor:pointer;font-size:13px;font-weight:600">📊 שמור CSV (אקסל)</button>');
                            printWin.document.write('</div>');
                            printWin.document.write('<h2 style="margin:0 0 4px">📊 דוח היתרים מול תב"ע</h2>');
