                                                                    <td style={{padding:'6px',color:stream.color}}>{stream.label}</td>
                                                                    {si === 0 ? <td rowSpan={activeStreams.length} style={{padding:'6px',textAlign:'center',color:'#9ca3af'}}>{svc.ageFrom}-{svc.ageTo}</td> : null}
                                                                    <td style={{padding:'6px',textAlign:'center'}}>{sd.children}</td>
